function initGallery(e){let t=["Tous"];const c=document.querySelector(".gallery");e.forEach(e=>{t.push(e.category),e.images.forEach((t,n)=>{const a=document.createElement("img");a.src=t.thumb_src,a.alt=t.alt||`Photographie ${n+1}`,a.dataset.category=e.category,a.dataset.full_size_src=t.full_size_src,a.loading="lazy",a.addEventListener("click",onImageClicked),c.appendChild(a)})}),initCategories(t),initImageViewer()}function initCategories(e){const t=document.querySelector("#categories");e.forEach((e,c)=>{const n=document.createElement("button");n.dataset.category=e,n.innerText=e,0==c&&n.classList.add("active"),n.addEventListener("click",t=>{applyFilter(e)}),t.appendChild(n)})}function initImageViewer(){const e=document.querySelector("#image-viewer");e.addEventListener("click",t=>{t.target==e&&(e.classList.add("hidden"),e.querySelector("img:not(button>img)").src="#")}),e.addEventListener("click",e=>{if(e.target instanceof HTMLButtonElement){const t=e.target.classList;t.contains("previous")?showPreviousImage():t.contains("next")&&showNextImage()}})}function onImageClicked(e){const t=document.querySelector("#image-viewer");t.querySelector("img:not(button>img)").src=e.target.dataset.full_size_src,t.classList.remove("hidden")}function getOpenedImageIndex(){let e=-1,t=Array.from(document.querySelectorAll(".gallery img"));t=t.filter(e=>!e.classList.contains("hidden"));const c=document.querySelector("#image-viewer>img");return t.forEach((t,n)=>{const a=c.src,i=t.dataset.full_size_src.replace("./","");a.includes(i)&&(e=n)}),e}function showPreviousImage(){let e=Array.from(document.querySelectorAll(".gallery img"));e=e.filter(e=>!e.classList.contains("hidden"));let t=getOpenedImageIndex();t=t-1>=0?t-1:e.length-1,e[t].click()}function showNextImage(){let e=Array.from(document.querySelectorAll(".gallery img"));e=e.filter(e=>!e.classList.contains("hidden"));let t=getOpenedImageIndex();t=t+1<e.length?t+1:0,e[t].click()}function applyFilter(e){let t=document.querySelectorAll("#categories button");t.forEach(t=>{t.classList.remove("active"),t.dataset.category==e&&t.classList.add("active")});let c=document.querySelectorAll(".gallery img");c.forEach(t=>{t.classList.remove("hidden"),"Tous"!=e&&t.dataset.category!=e&&t.classList.add("hidden")})}fetch("./assets/json/gallery.json").then(e=>e.json()).then(e=>{initGallery(e)});